CREATE TABLE "ResilienceExperiment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" VARCHAR(160) NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"name" VARCHAR(200) NOT NULL,"state" VARCHAR(32) NOT NULL,"category" VARCHAR(64) NOT NULL,"mode" VARCHAR(32) NOT NULL,"owner" VARCHAR(160) NOT NULL,"reviewer" VARCHAR(160),"riskClass" VARCHAR(32) NOT NULL,"environment" VARCHAR(32) NOT NULL,"targetId" UUID NOT NULL,"faultId" UUID NOT NULL,"hypothesis" JSONB NOT NULL,"expectedBehavior" JSONB NOT NULL,"abortCriteria" JSONB NOT NULL,"blastRadius" JSONB NOT NULL,"expiration" TIMESTAMP(3) NOT NULL,"timeoutSeconds" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ResilienceExperiment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentTarget" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" VARCHAR(160) NOT NULL,"name" VARCHAR(200) NOT NULL,"targetType" VARCHAR(64) NOT NULL,"environment" VARCHAR(32) NOT NULL,"syntheticOnly" BOOLEAN NOT NULL DEFAULT true,"productionSafe" BOOLEAN NOT NULL DEFAULT false,"allowlisted" BOOLEAN NOT NULL DEFAULT true,"scope" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentTarget_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentFault" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" VARCHAR(160) NOT NULL,"name" VARCHAR(160) NOT NULL,"category" VARCHAR(64) NOT NULL,"riskClass" VARCHAR(32) NOT NULL,"supportedTargets" JSONB NOT NULL,"maximumDurationSeconds" INTEGER NOT NULL,"maximumAffectedRequests" INTEGER NOT NULL,"maximumAffectedJobs" INTEGER NOT NULL,"rollbackBehavior" JSONB NOT NULL,"observabilityRequirements" JSONB NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentFault_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentExecution" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"experimentId" UUID NOT NULL,"experimentVersion" INTEGER NOT NULL,"state" VARCHAR(32) NOT NULL,"startedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),"requestedBy" VARCHAR(160) NOT NULL,"correlationId" VARCHAR(128),"stopReason" TEXT,"blastRadiusObserved" JSONB,"expected" JSONB NOT NULL,"actual" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentExecution_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentStep" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"stepNumber" INTEGER NOT NULL,"action" VARCHAR(120) NOT NULL,"state" VARCHAR(32) NOT NULL,"startedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),"input" JSONB NOT NULL,"output" JSONB,"errorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentStep_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentGuardrail" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"experimentId" UUID NOT NULL,"version" INTEGER NOT NULL,"name" VARCHAR(160) NOT NULL,"kind" VARCHAR(64) NOT NULL,"threshold" DECIMAL(20,6),"comparator" VARCHAR(16),"action" VARCHAR(32) NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentGuardrail_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentObservation" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"metricKey" VARCHAR(160) NOT NULL,"observedValue" DECIMAL(20,6),"status" VARCHAR(32) NOT NULL,"evidence" JSONB NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentObservation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentMetric" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"metricKey" VARCHAR(160) NOT NULL,"expectedValue" DECIMAL(20,6),"actualValue" DECIMAL(20,6),"unit" VARCHAR(32),"passed" BOOLEAN NOT NULL,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentMetric_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentHypothesis" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"experimentId" UUID NOT NULL,"version" INTEGER NOT NULL,"statement" VARCHAR(2000) NOT NULL,"expectedFailure" JSONB NOT NULL,"expectedRecovery" JSONB NOT NULL,"unacceptableOutcomes" JSONB NOT NULL,"measurableMetrics" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentHypothesis_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentResult" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"outcome" VARCHAR(32) NOT NULL,"expected" JSONB NOT NULL,"actual" JSONB NOT NULL,"assertions" JSONB NOT NULL,"recovery" JSONB NOT NULL,"customerImpact" JSONB NOT NULL,"residualRisk" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentResult_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentEvidence" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"experimentId" UUID NOT NULL,"executionId" UUID,"evidenceType" VARCHAR(80) NOT NULL,"reference" VARCHAR(1000) NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"payload" JSONB NOT NULL,"capturedBy" VARCHAR(160),"immutable" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentEvidence_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentApproval" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"experimentId" UUID NOT NULL,"experimentVersion" INTEGER NOT NULL,"targetId" UUID NOT NULL,"faultId" UUID NOT NULL,"durationSeconds" INTEGER NOT NULL,"blastRadius" JSONB NOT NULL,"approvedBy" VARCHAR(160) NOT NULL,"reason" VARCHAR(1000) NOT NULL,"status" VARCHAR(32) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentApproval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentRollback" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"executionId" UUID NOT NULL,"strategy" VARCHAR(64) NOT NULL,"state" VARCHAR(32) NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentRollback_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentSchedule" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"experimentId" UUID NOT NULL,"scheduledFor" TIMESTAMP(3) NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdBy" VARCHAR(160) NOT NULL,"revalidation" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentSchedule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentSuppression" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" VARCHAR(160) NOT NULL,"reason" VARCHAR(1000) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"disabledClass" VARCHAR(64),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentSuppression_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExperimentCertificate" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"experimentId" UUID,"executionId" UUID,"status" VARCHAR(32) NOT NULL,"dimensions" JSONB NOT NULL,"testedScenarios" JSONB NOT NULL,"passedScenarios" JSONB NOT NULL,"failedScenarios" JSONB NOT NULL,"untestedScenarios" JSONB NOT NULL,"knownLimitations" JSONB NOT NULL,"residualRisks" JSONB NOT NULL,"approvalAuthority" VARCHAR(160) NOT NULL,"certifiedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExperimentCertificate_pkey" PRIMARY KEY ("id"));
